// ---- generated by scripts/make_r2_tests.py of the probe: the readers
[[nodiscard]] std::string readBodyTube(ApplicationSetterFixture& fixture, const RocketComponent& c)
{
    return listInOrder(
        {presetPartNoOf(c), presetDigestOf(c), c.getName(), num(c.getLength()),
         num(as<BodyTube>(c).getOuterRadius()), flag(as<BodyTube>(c).isOuterRadiusAutomatic()),
         num(as<BodyTube>(c).getThickness()), as<BodyTube>(c).getMaterial().toStorableString(),
         flag(as<BodyTube>(c).getMaterial().isUserDefined()),
         flag(as<BodyTube>(c).getMaterial().isDocumentMaterial()),
         documentMaterialsOf(fixture.document())});
}

