{
    EXPECT_EQ(checkSetterScripts(kOwn), Texts{});
}

/// What OpenRocket holds after the case @p id of kJava; empty when kJava has no such case.
[[nodiscard]] std::string_view openRocketsAnswerTo(std::string_view id)
{
    for (const SetterScript& script : kJava)
    {
        if (script.id == id)
        {
            return script.expected;
        }
    }
    return {};
}

// For part R3 (ComponentParameterHandler): the rows of kJava that say what its bracket is for.
// They are the body tube of "3D printable nose cone and fins" with its elements in the file's
// order: <name>, <id>, <preset>, then <finish>, <material>, <length>, <thickness>, <radius>.
TEST(ComponentPresetSetter, TheElementsBehindAPresetTakeItsLinkAwayUnlessPresetClearingIsIgnored)
{
    // With RocketComponent::setIgnorePresetClearing(true): the file's values, and the preset.
    EXPECT_TRUE(openRocketsAnswerTo("p070").starts_with(
        "BT-50FE, 30359, e9c3e97d32e96762f65e051d74cb9fd7, Paper Body Tube -- DO NOT PRINT, "
        "0.15239999999999998, "));
    // Without: the same values, and no preset.
    EXPECT_TRUE(openRocketsAnswerTo("p080").starts_with(
        "null, null, Paper Body Tube -- DO NOT PRINT, 0.15239999999999998, "));
    // It is the <material> that does it here (its group is not the preset's)...
    EXPECT_TRUE(openRocketsAnswerTo("p072").starts_with("BT-50FE, 30359, "));
    EXPECT_TRUE(openRocketsAnswerTo("p082").starts_with("null, null, "));
    // ... a parachute's <diameter> and a nose cone's <length> do it as well.
    EXPECT_TRUE(openRocketsAnswerTo("p077").starts_with("PK-10, 2262, "));
    EXPECT_TRUE(openRocketsAnswerTo("p087").starts_with("null, null, "));
    EXPECT_TRUE(openRocketsAnswerTo("p079").starts_with("PNC-50YR, 72604, "));
    EXPECT_TRUE(openRocketsAnswerTo("p089").starts_with("null, null, "));
    // The preset's material reaches the document before the file's, and a save writes the two
    // in that order (the last value of a row: the document's materials).
    EXPECT_TRUE(openRocketsAnswerTo("p070").ends_with(
        "BULK|Paper, spiral kraft glassine, Estes avg, bulk|894.4|0.0|Other; "
        "BULK|Paper, spiral kraft glassine, Estes avg, bulk|894.4|0.0|Custom"));
}

/// The <preset> element of the body tube of "3D printable nose cone and fins".
constexpr std::string_view kBodyTubePreset =
    "type=BODY_TUBE|manufacturer=Estes|partno=BT-50FE, 30359|"
    "digest=e9c3e97d32e96762f65e051d74cb9fd7";

/// Applies the entry @p key of the setter table to @p component; false when the table has no
/// such setter or the setter fails.
[[nodiscard]] bool applyKey(ApplicationSetterFixture& fixture, RocketComponent& component,
                            std::string_view key, std::string_view attributes,
                            std::string_view text, WarningSet& warnings)
{
    const Setter* const setter = setterOfKey(key);
    return setter != nullptr &&
           setter->set(component, text, attributesOf(attributes), warnings, fixture.context())
               .has_value();
}

/// What the body tube's <preset> gives a body tube when the context has the preset database
/// @p database: the part number of the tube's preset, then the warnings in brackets.
[[nodiscard]] std::string loadWithDatabase(const ComponentPresetDatabase* database)
{
    ApplicationSetterFixture fixture;
    fixture.context().setComponentPresetDatabase(database);
    RocketComponent& tube = fixture.make(ComponentKind::BODY_TUBE);
    WarningSet       warnings;
    if (!applyKey(fixture, tube, "RocketComponent:preset", kBodyTubePreset, "", warnings))
    {
        return "no setter, or it failed";
    }
    return withWarnings(presetPartNoOf(tube), warnings);
}

// The product until it reads preset files (Milestone 3): OpenRocket with an empty preset
// database gives the same warning (the scouts' examples-no-presets.out).
TEST(ComponentPresetSetter, WithoutAPresetDatabaseOrWithAnEmptyOneNoPresetIsFound)
{
    const ComponentPresetDatabase empty;
    EXPECT_EQ(loadWithDatabase(nullptr),
              "null [No matching ComponentPreset for component Body Tube found matching Estes "
              "BT-50FE, 30359]");
    EXPECT_EQ(loadWithDatabase(&empty),
              "null [No matching ComponentPreset for component Body Tube found matching Estes "
              "BT-50FE, 30359]");
}

/// The part number of the preset a body tube keeps when the database it came from is gone.
[[nodiscard]] std::string partNoAfterTheDatabaseIsGone()
{
    ApplicationSetterFixture fixture;
    RocketComponent&         tube = fixture.make(ComponentKind::BODY_TUBE);
    WarningSet               warnings;
    {
        const ComponentPresetDatabase database = QtRocket::Test::makeExamplePresetDatabase();
        fixture.context().setComponentPresetDatabase(&database);
        if (!applyKey(fixture, tube, "RocketComponent:preset", kBodyTubePreset, "", warnings))
        {
            return "no setter, or it failed";
        }
        fixture.context().setComponentPresetDatabase(nullptr);
    }
    return withWarnings(presetPartNoOf(tube), warnings);
}

// The context's database is only read while a file loads: the component co-owns its preset.
TEST(ComponentPresetSetter, TheComponentSharesThePresetWithTheDatabase)
{
    EXPECT_EQ(partNoAfterTheDatabaseIsGone(), "BT-50FE, 30359");
}

/// What <preset> does in a rocket that is frozen: the part number of the tube's preset and
/// whether the rocket is still frozen, then the warnings in brackets.
[[nodiscard]] std::string loadIntoAFrozenRocket()
{
    ApplicationSetterFixture fixture;
    RocketComponent&         tube = fixture.make(ComponentKind::BODY_TUBE);
    WarningSet               warnings;
    fixture.rocket().freeze();
    const bool applied =
        applyKey(fixture, tube, "RocketComponent:preset", kBodyTubePreset, "", warnings);
    std::string told = listInOrder({presetPartNoOf(tube), flag(fixture.rocket().isFrozen())});
    fixture.rocket().thaw();
    return applied ? withWarnings(std::move(told), warnings) : "no setter, or it failed";
}

// No loader freezes the rocket (its events are on while a file loads). RocketComponent::
// loadPreset() has a BugError for a frozen rocket, which the setter must not run into.
TEST(ComponentPresetSetter, AFrozenRocketLoadsNoPreset)
{
    EXPECT_EQ(loadIntoAFrozenRocket(), "null, true [Invalid parameter encountered, ignoring.]");
}

/// The kind of component that takes a preset of @p type in the example designs.
[[nodiscard]] ComponentKind kindOf(ComponentPresetType type)
{
    switch (type)
    {
        case ComponentPresetType::PARACHUTE:
            return ComponentKind::PARACHUTE;
        case ComponentPresetType::NOSE_CONE:
            return ComponentKind::NOSE_CONE;
        default:
            return ComponentKind::BODY_TUBE;
    }
}

/// What the <preset> element @p reference of an example design gives a new component of its
/// kind, through the entry the walk for that kind finds: "<class of the entry> <digest of the
/// component's preset>", then the warnings in brackets.
[[nodiscard]] std::string loadExamplePreset(const ExamplePresetReference& reference)
{
    ApplicationSetterFixture           fixture;
    const ComponentKind                kind      = kindOf(reference.type);
    RocketComponent&                   component = fixture.make(kind);
    const DocumentConfig::SetterLookup lookup    = DocumentConfig::findSetter(kind, "preset");
    WarningSet                         warnings;
    const std::string                  attributes = std::format(
        "type={}|manufacturer={}|partno={}|digest={}", componentPresetTypeName(reference.type),
        reference.manufacturer, reference.partNo, reference.digest);
    if (lookup.setter == nullptr ||
        !lookup.setter->set(component, "", attributesOf(attributes), warnings, fixture.context())
             .has_value())
    {
        return "no setter, or it failed";
    }
    return withWarnings(std::format("{} {}", lookup.owner, presetDigestOf(component)), warnings);
}

/// loadExamplePreset() of every <preset> element of the example designs.
[[nodiscard]] Texts loadEveryExamplePreset()
{
    Texts loaded;
    for (const ExamplePresetReference& reference : kExamplePresetReferences)
    {
        loaded.push_back(loadExamplePreset(reference));
    }
    return loaded;
}

// The six <preset> elements of the 16 example designs, each through the entry the handler of a
// component's parameters will find for it: a parachute's own entry hides RocketComponent's.
TEST(ComponentPresetSetter, FindsEveryPresetOfTheExampleDesigns)
{
    EXPECT_EQ(loadEveryExamplePreset(),
              (Texts{"RocketComponent e9c3e97d32e96762f65e051d74cb9fd7",
                     "Parachute b595c8a31baaf325291d5c957f3940f8",
                     "Parachute 9a96b8806749e790db29bacfbc70eb1e",
                     "RocketComponent 18363dec5642206a109389ef48efcb32",
                     "RocketComponent a59dec8e4034a2fee5955dbf4ff07f1c",
                     "RocketComponent 6f564a198c80de3af437608827fa1bc1"}));
}

/// A parachute preset with a packed length and diameter, which none of the presets of the
/// example designs has: the preset the probe makes for its cases k000 to k004 (--packed), from
/// the same property values.
[[nodiscard]] std::shared_ptr<const ComponentPreset> makePackedPreset()
{
    TypedPropertyMap props;
    props.put(ComponentPreset::kLegacy, false);
    props.put(ComponentPreset::kManufacturer, Manufacturer::getManufacturer("Estes"));
    props.put(ComponentPreset::kPartNo, "PK-PACKED");
    props.put(ComponentPreset::kDescription, "Parachute with packed dimensions");
    props.put(
        ComponentPreset::kMaterial,
        Material::newMaterial(Material::Type::SURFACE, "Polyethylene film, HDPE, 1.0 mil, bare",
                              0.0235, MaterialGroup::OTHER, true, true));
    props.put(ComponentPreset::kType, ComponentPresetType::PARACHUTE);
    props.put(ComponentPreset::kDiameter, 0.3);
    props.put(ComponentPreset::kLineCount, 8);
    props.put(ComponentPreset::kLineLength, 0.35);
    props.put(ComponentPreset::kSides, 8);
    props.put(ComponentPreset::kLineMaterial,
              Material::newMaterial(Material::Type::LINE, "Carpet Thread", 3.3E-4,
                                    MaterialGroup::OTHER, true, true));
    props.put(ComponentPreset::kPackedLength, 0.04);
    props.put(ComponentPreset::kPackedDiameter, 0.02);
    const MaterialStorage materials;
    return std::make_shared<const ComponentPreset>(
        ComponentPresetFactory::create(props, materials).value());
}

/// What a parachute holds after <preset> of the packed preset through the entry @p key, behind
/// <packedradius> with @p radiusBefore when that is not empty: the part number of its preset,
/// its name, diameter, line count and line length, its packed radius, whether that is automatic
/// and its packed length; then the warnings in brackets.
[[nodiscard]] std::string loadThePackedPreset(std::string_view key, std::string_view radiusBefore)
{
    ApplicationSetterFixture                     fixture;
    const std::shared_ptr<const ComponentPreset> preset = makePackedPreset();
    fixture.presets().add(preset);
    RocketComponent&  chute = fixture.make(ComponentKind::PARACHUTE);
    WarningSet        warnings;
    const std::string attributes = std::format(
        "type=PARACHUTE|manufacturer=Estes|partno=PK-PACKED|digest={}", preset->getDigest());
    const bool radiusSet =
        radiusBefore.empty() ||
        applyKey(fixture, chute, "MassObject:packedradius", "", radiusBefore, warnings);
    if (!radiusSet || !applyKey(fixture, chute, key, attributes, "", warnings))
    {
        return "no setter, or it failed";
    }
    const auto& parachute = as<Parachute>(chute);
    // The packed radius before the packed length: asking for an automatic radius sets the length.
    return withWarnings(listInOrder({presetPartNoOf(chute), chute.getName(),
                                     num(parachute.getDiameter()), count(parachute.getLineCount()),
                                     num(parachute.getLineLength()), num(parachute.getRadius()),
                                     flag(parachute.isRadiusAutomatic()), num(chute.getLength())}),
                        warnings);
}

// The cases k000 to k004 of the probe. A parachute's entry loads its preset with Java's extra
// parameter `false`: the packed radius is the preset's and not automatic. Through the entry of
// RocketComponent, which no file reaches for a parachute, the preset makes it automatic.
TEST(ComponentPresetSetter, AParachutesEntryKeepsThePackedRadiusOfThePreset)
{
    EXPECT_EQ(makePackedPreset()->getDigest(), "1ea55ef70a493c644ee8b00ede13b1dc");
    EXPECT_EQ(loadThePackedPreset("Parachute:preset", ""),
              "PK-PACKED, Parachute, 0.3, 8, 0.35, 0.01, false, 0.04");
    EXPECT_EQ(loadThePackedPreset("RocketComponent:preset", ""),
              "PK-PACKED, Parachute, 0.3, 8, 0.35, 0.023, true, 0.007561436672967866");
    EXPECT_EQ(loadThePackedPreset("Parachute:preset", "auto 0.01"),
              "PK-PACKED, Parachute, 0.3, 8, 0.35, 0.01, false, 0.04");
    EXPECT_EQ(loadThePackedPreset("RocketComponent:preset", "auto 0.01"),
              "PK-PACKED, Parachute, 0.3, 8, 0.35, 0.023, true, 0.007561436672967866");
    EXPECT_EQ(loadThePackedPreset("Parachute:preset", "0.01"),
              "PK-PACKED, Parachute, 0.3, 8, 0.35, 0.01, false, 0.04");
}

/// A body tube preset whose material is the bulk material @p materialName of @p density: the
/// presets of the probe ShortMaterialProbe (tier 9b, the fixer of the rocket side), from the
/// same property values.
[[nodiscard]] std::shared_ptr<const ComponentPreset> makeTubePreset(std::string_view partNo,
                                                                    std::string_view materialName,
                                                                    double           density)
{
    TypedPropertyMap props;
    props.put(ComponentPreset::kLegacy, false);
    props.put(ComponentPreset::kManufacturer, Manufacturer::getManufacturer("Estes"));
    props.put(ComponentPreset::kPartNo, std::string(partNo));
    props.put(ComponentPreset::kDescription, std::format("Body tube {}", partNo));
    props.put(ComponentPreset::kType, ComponentPresetType::BODY_TUBE);
    props.put(ComponentPreset::kLength, 0.2);
    props.put(ComponentPreset::kOuterDiameter, 0.03);
    props.put(ComponentPreset::kInnerDiameter, 0.028);
    props.put(ComponentPreset::kMaterial,
              Material::newMaterial(Material::Type::BULK, std::string(materialName), density,
                                    MaterialGroup::OTHER, true, true));
    const MaterialStorage materials;
    return std::make_shared<const ComponentPreset>(
        ComponentPresetFactory::create(props, materials).value());
}

/// The digest of the preset makeTubePreset() makes and the length of its material's text as
/// Java counts it (Material.toString().length()).
[[nodiscard]] std::string tubePresetFacts(std::string_view partNo, std::string_view materialName,
                                          double density)
{
    const std::shared_ptr<const ComponentPreset> preset =
        makeTubePreset(partNo, materialName, density);
    return std::format(
        "{} {}", preset->getDigest(),
        QtRocket::Strings::javaLength(preset->get(ComponentPreset::kMaterial).toString()));
}

/// What a recovery device of @p kind holds after <preset> of the body tube preset
/// makeTubePreset() makes through the entry @p key: the part number of its preset, its name,
/// its length and its material; then the warnings in brackets.
[[nodiscard]] std::string loadATubePresetIntoADevice(std::string_view key, ComponentKind kind,
                                                     std::string_view partNo,
                                                     std::string_view materialName, double density)
{
    ApplicationSetterFixture                     fixture;
    const std::shared_ptr<const ComponentPreset> preset =
        makeTubePreset(partNo, materialName, density);
    fixture.presets().add(preset);
    RocketComponent&  device = fixture.make(kind);
    WarningSet        warnings;
    const std::string attributes = std::format(
        "type=BODY_TUBE|manufacturer=Estes|partno={}|digest={}", partNo, preset->getDigest());
    if (!applyKey(fixture, device, key, attributes, "", warnings))
    {
        return "no setter, or it failed";
    }
    return withWarnings(
        listInOrder({presetPartNoOf(device), device.getName(), num(device.getLength()),
                     as<QtRocket::RecoveryDevice>(device).getMaterial().toStorableString()}),
        warnings);
}

// The review's finding: the setter refused every preset whose material is no surface material
// for a parachute or streamer. OpenRocket's devices (and RecoveryDevice::loadFromPreset()) take
// a preset's material only when its text, "name (density)", is longer than 12 characters; a
// preset with a shorter one is loaded whatever the material's type, and the device keeps its
// default material. Pinned with OpenRocket (ShortMaterialProbe.out): texts of 11 and 12
// characters load, texts of 13 and 22 end in its ClassCastException.
TEST(ComponentPresetSetter, ARecoveryDeviceTakesAPresetWhoseShortMaterialItPassesOver)
{
    EXPECT_EQ(tubePresetFacts("BT-SHORT", "A", 0.0), "5f37a9028648c49d5ed3b959a1a787c3 11");
    EXPECT_EQ(tubePresetFacts("BT-TWELVE", "Ab", 0.0), "fb3eae768385e4feeeb2ff2cabcc044b 12");

    constexpr std::string_view kNylon = "SURFACE|Ripstop nylon|0.067|0.0|Fabrics";
    EXPECT_EQ(loadATubePresetIntoADevice("Parachute:preset", ComponentKind::PARACHUTE, "BT-SHORT",
                                         "A", 0.0),
              std::format("BT-SHORT, Parachute, 0.2, {}", kNylon));
    EXPECT_EQ(loadATubePresetIntoADevice("RocketComponent:preset", ComponentKind::STREAMER,
                                         "BT-SHORT", "A", 0.0),
              std::format("BT-SHORT, Streamer, 0.05, {}", kNylon));
    EXPECT_EQ(loadATubePresetIntoADevice("Parachute:preset", ComponentKind::PARACHUTE, "BT-TWELVE",
                                         "Ab", 0.0),
              std::format("BT-TWELVE, Parachute, 0.2, {}", kNylon));
    EXPECT_EQ(loadATubePresetIntoADevice("RocketComponent:preset", ComponentKind::STREAMER,
                                         "BT-TWELVE", "Ab", 0.0),
              std::format("BT-TWELVE, Streamer, 0.05, {}", kNylon));
}

// One character more, and the device would take the material: a bulk material, of which
// OpenRocket dies (with the preset's length of 0.2 set already) and which is refused here
// before anything is loaded, so the length stays the device's 0.025.
TEST(ComponentPresetSetter, ARecoveryDeviceIsNotGivenAPresetWhoseLongerMaterialDoesNotFit)
{
    EXPECT_EQ(tubePresetFacts("BT-THIRTEEN", "Abc", 0.0), "70cf22c9b062f0b346f760c5cbcd31e8 13");
    EXPECT_EQ(tubePresetFacts("BT-LONG", "Cardboard", 680.0),
              "0c6814453f6f6eeb0838d327a6426dfd 22");

    constexpr std::string_view kRefused =
        "0.025, SURFACE|Ripstop nylon|0.067|0.0|Fabrics [Invalid parameter encountered, ignoring.]";
    EXPECT_EQ(loadATubePresetIntoADevice("Parachute:preset", ComponentKind::PARACHUTE,
                                         "BT-THIRTEEN", "Abc", 0.0),
              std::format("null, Parachute, {}", kRefused));
    EXPECT_EQ(loadATubePresetIntoADevice("RocketComponent:preset", ComponentKind::STREAMER,
                                         "BT-THIRTEEN", "Abc", 0.0),
              std::format("null, Streamer, {}", kRefused));
    EXPECT_EQ(loadATubePresetIntoADevice("Parachute:preset", ComponentKind::PARACHUTE, "BT-LONG",
                                         "Cardboard", 680.0),
              std::format("null, Parachute, {}", kRefused));
    EXPECT_EQ(loadATubePresetIntoADevice("RocketComponent:preset", ComponentKind::STREAMER,
                                         "BT-LONG", "Cardboard", 680.0),
              std::format("null, Streamer, {}", kRefused));
}

/// What a setter of the test's own, whose function only notes the preset it is handed, does
/// with the body tube's <preset>: the part number it was handed, or "nothing".
[[nodiscard]] std::string presetHandedOver()
{
    std::string                 handed = "nothing";
    const ComponentPresetSetter setter(
        [&handed](RocketComponent& /*component*/,
                  const std::shared_ptr<const ComponentPreset>& preset) {
            handed = preset->getPartNo();
        });
    ApplicationSetterFixture fixture;
    WarningSet               warnings;
    if (!setter
             .set(fixture.setters().tube(), "", attributesOf(kBodyTubePreset), warnings,
                  fixture.context())
             .has_value())
    {
        return "the setter failed";
    }
    return withWarnings(std::move(handed), warnings);
}

TEST(ComponentPresetSetter, HandsThePresetItFoundToItsFunction)
{
    EXPECT_EQ(presetHandedOver(), "BT-50FE, 30359");
    EXPECT_THROW(ComponentPresetSetter(ComponentPresetSetter::LoadFunction{}), BugError);
}

